    import numpy as np

    dtype = getattr(data, "dtype", None)
    if dtype is None:
        return False
    if not hasattr(dtype, "kind") or dtype.kind != "O":
        return False
    try:
        import cftime
    except ImportError:
        return False
    try:
        if hasattr(data, "compute"):
            flat = data.ravel()
            sample = flat[: min(10, flat.size)]
            actual = sample.compute() if hasattr(sample, "compute") else sample
        else:
            actual = np.asarray(data).ravel()
        return any(isinstance(x, cftime.datetime) for x in actual.flat[:100])
    except Exception:
        return False


